<script setup>
import { computed,ref } from 'vue'
import { Plus, Minus, X } from 'lucide-vue-next'
import { useCartStore } from '../stores/cart.js'
import { useCatalogStore } from '../stores/catalog.js'
import { price, displayProductName } from '../utils/catalog.js'
import LoadState from '../components/ui/LoadState.vue'
const cart=useCartStore(),catalog=useCatalogStore(),notice=ref(false),promo=ref(''),bonus=ref('')
const items=computed(()=>cart.lines.map(line=>({...line,product:catalog.byId(line.id)})).filter(x=>x.product))
const subtotal=computed(()=>items.value.reduce((sum,x)=>sum+x.product.salePrice*x.quantity,0))
const shipping=computed(()=>items.value.length?0:0)
</script>
<template><section class="container cart-page"><LoadState v-if="catalog.loading||catalog.error" :loading="catalog.loading" :error="catalog.error" @retry="catalog.load(true)"/><div v-else class="cart-layout"><div class="cart-left"><h1>Shopping Cart</h1><template v-if="items.length"><article v-for="item in items" :key="item.id" class="cart-row"><RouterLink :to="`/product/${item.id}`" class="cart-photo"><img v-if="item.product.images[0]" :src="item.product.images[0]" :alt="item.product.name"/></RouterLink><div class="cart-info"><RouterLink :to="`/product/${item.id}`" class="cart-product-name">{{ displayProductName(item.product) }}</RouterLink><small>#{{ item.id }}</small></div><div class="cart-qty"><button type="button" :aria-label="`Decrease ${item.product.name}`" @click="cart.setQuantity(item.id,item.quantity-1)"><Minus :size="20"/></button><span>{{ item.quantity }}</span><button type="button" :aria-label="`Increase ${item.product.name}`" @click="cart.setQuantity(item.id,item.quantity+1)"><Plus :size="20"/></button></div><strong>{{ price(item.product.salePrice*item.quantity) }}</strong><button type="button" class="cart-delete" :aria-label="`Remove ${item.product.name}`" @click="cart.remove(item.id)"><X :size="24" :stroke-width="1.4"/></button></article></template><p v-else class="empty-cart">Your shopping cart is empty. <RouterLink to="/catalog">Shop now</RouterLink></p></div><aside class="order-summary"><h2>Order Summary</h2><label>Discount code / Promo code<input v-model="promo" type="text" placeholder="Code"/></label><label>Your bonus card number<div class="bonus-input"><input v-model="bonus" type="text" placeholder="Enter Card Number"/><button type="button" class="outline-button" @click="notice=true">Apply</button></div></label><div class="summary-line"><strong>Subtotal</strong><strong>{{ price(subtotal) }}</strong></div><div class="summary-line muted"><span>Estimated Tax</span><span>Calculated at checkout</span></div><div class="summary-line muted"><span>Estimated shipping & Handling</span><span>{{ shipping ? price(shipping) : 'Free' }}</span></div><div class="summary-line summary-total"><strong>Total</strong><strong>{{ price(subtotal+shipping) }}</strong></div><button class="buy-button checkout" :disabled="!items.length" @click="notice=true">Checkout</button><small class="checkout-note">Demo checkout: the provided backend has no order endpoint.</small></aside></div><div v-if="notice" class="modal-backdrop" @click.self="notice=false"><div class="notice-modal" role="dialog" aria-modal="true"><button type="button" @click="notice=false" class="cart-delete" aria-label="Close"><X/></button><h2>Demo mode</h2><p>Checkout and promo-code validation require backend endpoints that are not available in this assignment.</p><button class="buy-button" @click="notice=false">OK</button></div></div></section></template>
